const store = new Map();

function get(key) {
  const entry = store.get(key);
  if (!entry) return undefined;
  if (Date.now() > entry.expires) {
    store.delete(key);
    return undefined;
  }
  return entry.value;
}

function set(key, value, ttlMs = 60000) {
  store.set(key, { value, expires: Date.now() + ttlMs });
}

module.exports = { get, set };

